const MANIFEST_URL = 'previews/manifest.json';

/** Loads the site catalog generated by scripts/build.py. Throws if it can't be loaded. */
export async function loadCatalog() {
    const res = await fetch(MANIFEST_URL);
    if (!res.ok) throw new Error(`Could not load ${MANIFEST_URL}: HTTP ${res.status}`);
    return res.json();
}

export function findBusiness(catalog, id) {
    return catalog.find(business => business.id === id) ?? null;
}
